// @domain: domains
//! #4493 — the same API on an embedded store: the real SPARQL row logic and the real
//! door rules, on Oxigraph in memory, with no Fuseki. Includes the backup and restore
//! drill (Silas's review, point 3). Generated by athena-gen — DO NOT EDIT.

use crate::auth::{self, Caller};
use crate::model::{ClassDef, CLASSES, NS};
use crate::store::{iri, Embedded, Engine, RowStore, Sparql};
use crate::{write, Ctx};
use serde_json::{json, Value};

fn class_with_link() -> &'static ClassDef {
    CLASSES.iter().find(|c| c.fields.iter().any(|f| f.link && f.name != "ownedBy")).expect("a class with a link field")
}

fn caller(name: &str) -> Caller {
    Caller { principal: name.into(), web_id: format!("https://id.example/{name}"), scopes: Vec::new() }
}

/// A store holding one principal and one target row per link field.
fn seeded() -> Embedded {
    let e = Embedded::memory();
    let mut triples = vec![format!("<{NS}principal-wren> a <{NS}Principal> .")];
    for c in CLASSES {
        for f in c.fields.iter().filter(|f| f.link && f.name != "ownedBy") {
            triples.push(format!("<{NS}target-{}> a <{NS}Target> .", f.name));
        }
    }
    e.update(&format!("INSERT DATA {{ GRAPH <urn:test:seed> {{ {} }} }}", triples.join(" "))).unwrap();
    e
}

fn body_for(c: &ClassDef, name: &str) -> String {
    let mut b = serde_json::Map::new();
    b.insert("name".into(), json!(name));
    for f in c.fields.iter().filter(|f| f.name != "ownedBy" && (f.required || f.link)) {
        let v = if f.link { format!("target-{}", f.name) } else { f.allowed.first().map(|a| a.to_string()).unwrap_or_else(|| "2026-10-10T00:00:00Z".into()) };
        b.insert(f.name.into(), json!(v));
    }
    Value::Object(b).to_string()
}

fn ctx<'a>(store: &'a Sparql) -> Ctx<'a> {
    let who = Box::leak(Box::new(auth::build("http://127.0.0.1:9/", |_| None)));
    Ctx { store, who, events: String::new(), reads_public: true }
}

#[test]
fn create_then_read_back_on_the_embedded_store() {
    let c = class_with_link();
    let store = Sparql::over(Box::new(seeded()));
    let (code, out) = write(&ctx(&store), &caller("wren"), "POST", c, None, &body_for(c, "e1"));
    assert_eq!(code, 201, "{out}");
    let row = store.get(c, "e1").unwrap().expect("the row reads back");
    assert_eq!(row["name"], json!("e1"));
    assert_eq!(row["ownedBy"], json!("principal-wren"));
    let (rows, total) = store.list(c, 10, 0).unwrap();
    assert_eq!((rows.len(), total), (1, 1));
}

#[test]
fn a_wrong_kind_link_is_removed_by_the_real_update() {
    let c = class_with_link();
    let f = c.fields.iter().find(|f| f.link && f.name != "ownedBy").unwrap();
    let e = seeded();
    let store = Sparql::over(Box::new(e));
    write(&ctx(&store), &caller("wren"), "POST", c, None, &body_for(c, "e2"));
    // a stray value of the wrong kind, as heralds held c:Proving (#4482)
    let stray = format!("INSERT DATA {{ GRAPH <{}> {{ <{}> <{NS}{}> <{NS}Proving> }} }}", c.graph, iri(c, "e2"), f.name);
    store_engine(&store).update(&stray).unwrap();
    let (code, out) = write(&ctx(&store), &caller("wren"), "PATCH", c, Some("e2"), &json!({ f.name: format!("target-{}", f.name) }).to_string());
    assert_eq!(code, 200, "{out}");
    let row = store.get(c, "e2").unwrap().unwrap();
    let got = if f.many { row[f.name].clone() } else { json!([row[f.name].clone()]) };
    assert_eq!(got, json!([format!("target-{}", f.name)]), "the stray c:Proving must be gone");
}

#[test]
fn a_link_to_nothing_is_refused_on_the_embedded_store_too() {
    let c = class_with_link();
    let f = c.fields.iter().find(|f| f.link && f.name != "ownedBy").unwrap();
    let store = Sparql::over(Box::new(seeded()));
    write(&ctx(&store), &caller("wren"), "POST", c, None, &body_for(c, "e3"));
    let (code, out) = write(&ctx(&store), &caller("wren"), "PATCH", c, Some("e3"), &json!({ f.name: "nobody-here" }).to_string());
    assert_eq!((code, out["error"].as_str()), (422, Some("unknown-target")), "{out}");
}

#[test]
fn backup_and_restore_drill_keeps_every_row() {
    let c = class_with_link();
    let e = seeded();
    let store = Sparql::over(Box::new(e));
    for n in ["d1", "d2", "d3"] {
        let (code, out) = write(&ctx(&store), &caller("wren"), "POST", c, None, &body_for(c, n));
        assert_eq!(code, 201, "{out}");
    }
    write(&ctx(&store), &caller("wren"), "PATCH", c, Some("d1"), &json!({ "label": "changed" }).to_string());
    let dump = store_embedded(&store).dump_trig().unwrap();
    let restored = Embedded::memory();
    restored.load_trig(&dump).unwrap();
    let back = Sparql::over(Box::new(restored));
    let (rows, total) = back.list(c, 10, 0).unwrap();
    assert_eq!(total, 3, "every row survives the round trip");
    assert_eq!(rows.iter().find(|r| r["name"] == json!("d1")).unwrap()["label"], json!("changed"));
    assert_eq!(back.version_count(&format!("{}/d1", c.plural)).unwrap(), 1, "kept versions survive too");
}

#[test]
fn negative_proof_a_dump_missing_a_row_is_caught() {
    let c = class_with_link();
    let store = Sparql::over(Box::new(seeded()));
    for n in ["n1", "n2"] {
        write(&ctx(&store), &caller("wren"), "POST", c, None, &body_for(c, n));
    }
    let dump = store_embedded(&store).dump_trig().unwrap();
    let restored = Embedded::memory();
    restored.load_trig(&dump).unwrap();
    // a restore that lost a row: the drill's count must see it
    restored.update(&format!("DELETE WHERE {{ GRAPH <{}> {{ <{}> ?p ?o }} }}", c.graph, iri(c, "n2"))).unwrap();
    let (_, total) = Sparql::over(Box::new(restored)).list(c, 10, 0).unwrap();
    assert_ne!(total, 2, "a lossy dump must not restore every row");
}

fn store_engine(s: &Sparql) -> &dyn Engine {
    s.engine()
}

fn store_embedded(s: &Sparql) -> &Embedded {
    s.embedded().expect("an embedded engine")
}

// ── #4524: reads show a caller only their own rows and the rows granted to them ──

fn any_class() -> &'static ClassDef {
    CLASSES.iter().find(|c| c.fields.iter().any(|f| f.name == "ownedBy")).expect("a class with an owner")
}

/// Two members, Art and Jennifer, each owning one row; a stranger owning nothing.
fn two_owners(grant: Option<(&str, &str)>) -> Sparql {
    let c = any_class();
    let e = Embedded::memory();
    let row = |who: &str| format!("<{s}> a <{NS}{cls}> ; <{NS}ownedBy> <{NS}principal-{who}> .", s = iri(c, &format!("row-{who}")), cls = c.name);
    e.update(&format!("INSERT DATA {{ GRAPH <{g}> {{ {a} {j} }} }}", g = c.graph, a = row("art"), j = row("jennifer"))).unwrap();
    if let Some((mode, target)) = grant {
        e.update(&format!(
            "INSERT DATA {{ GRAPH <urn:test:grants> {{ <{NS}permission-t> a <{NS}Permission> ; <{NS}agent> <{NS}principal-jennifer> ; <{NS}accessTo> \"{target}\" ; <{NS}mode> <http://www.w3.org/ns/auth/acl#{mode}> }} }}"
        )).unwrap();
    }
    Sparql::over(Box::new(e))
}

fn names(rows: &[crate::store::Row]) -> Vec<String> {
    let mut n: Vec<String> = rows.iter().map(|r| r["name"].as_str().unwrap_or("").to_string()).collect();
    n.sort();
    n
}

#[test]
fn each_member_sees_only_their_own_rows_and_count() {
    let (c, s) = (any_class(), two_owners(None));
    let (rows, total) = s.list_seen_by(c, 10, 0, &format!("{NS}principal-art")).unwrap();
    assert_eq!((names(&rows), total), (vec!["row-art".to_string()], 1), "the count is Art's, not the store's");
    let (rows, total) = s.list_seen_by(c, 10, 0, &format!("{NS}principal-stranger")).unwrap();
    assert_eq!((rows.len(), total), (0, 0), "a stranger sees nothing, and not even how much there is");
    assert!(s.get_seen_by(c, "row-art", &format!("{NS}principal-jennifer")).unwrap().is_none(), "Art's row is not Jennifer's");
}

#[test]
fn a_read_grant_on_one_row_opens_that_row() {
    let c = any_class();
    let s = two_owners(Some(("Read", &iri(c, "row-art"))));
    let (rows, _) = s.list_seen_by(c, 10, 0, &format!("{NS}principal-jennifer")).unwrap();
    assert_eq!(names(&rows), vec!["row-art".to_string(), "row-jennifer".to_string()]);
}

#[test]
fn a_read_grant_on_a_member_opens_everything_they_own() {
    let c = any_class();
    let s = two_owners(Some(("Read", &format!("{NS}principal-art"))));
    assert!(s.get_seen_by(c, "row-art", &format!("{NS}principal-jennifer")).unwrap().is_some());
}

#[test]
fn negative_proof_an_append_grant_does_not_open_reads() {
    let c = any_class();
    let s = two_owners(Some(("Append", &iri(c, "row-art"))));
    let (rows, total) = s.list_seen_by(c, 10, 0, &format!("{NS}principal-jennifer")).unwrap();
    assert_eq!((names(&rows), total), (vec!["row-jennifer".to_string()], 1));
}

#[test]
fn sign_in_reads_this_store_not_a_remote_one() {
    // #4524 S1: the checker's queries are answered by the product's own engine. The
    // closure here is the one main() builds; no endpoint exists in this test at all.
    let e = Embedded::memory();
    let home = format!("{}domains:security", chorus_oidc::identity_model::identity_model().graph_prefix);
    e.update(&format!("INSERT DATA {{ GRAPH <{home}> {{ <{NS}principal-art> a <{NS}Principal> ; <{NS}webId> \"https://id.example/art#me\" }} }}")).unwrap();
    let engine: std::sync::Arc<dyn Engine> = std::sync::Arc::new(e);
    let q = { let e = engine.clone(); move |q: &str| e.select_json(q).ok() };
    let ids = chorus_oidc::oidc::resolve_principal_webids(&q).expect("the store answered");
    assert_eq!(ids, vec!["https://id.example/art#me".to_string()]);
}

/// #4757 — the root header is retired: GET /<product> is an unknown route, never a header.
#[test]
fn the_product_root_is_no_header() {
    let store = Sparql::over(Box::new(seeded()));
    let (code, out) = crate::route(&ctx(&store), "GET", &format!("/{}", crate::model::PRODUCT), None, "");
    assert_eq!(code, 404, "{out}");
    assert_ne!(out["kind"], json!("Header"), "{out}");
}

/// #4744 AC8 (Jeff 10-26: "filter and search on any domain like a stream") — every
/// collection takes the same filter (`<field>=<value>`) and text search (`q=`), run in the
/// store before the page is cut, so the count is the count of matches.
#[test]
fn every_collection_filters_and_searches_in_the_store() {
    let (c, f) = CLASSES.iter()
        .find_map(|c| c.fields.iter().find(|f| !f.link && !f.many && f.datatype == "string" && f.allowed.is_empty()).map(|f| (c, f.name)))
        .expect("a class with a free string field");
    let store = Sparql::over(Box::new(Embedded::memory()));
    for (n, v) in [("r1", "alpha one"), ("r2", "beta two")] {
        let cells = [(f.to_string(), vec![crate::rules::Cell::Literal(v.into(), "string")])];
        store.write(c.graph, &iri(c, n), Some(c.name), &cells, false).unwrap();
    }
    let ctx = ctx(&store);
    let path = format!("/{}/{}/{}", crate::model::PRODUCT, c.domain, c.segment);
    let get = |q: &str| crate::route(&ctx, "GET", &format!("{path}?{q}"), None, "");
    let names = |out: &Value| out["data"].as_array().unwrap().iter().map(|r| r["name"].as_str().unwrap().to_string()).collect::<Vec<_>>();

    let (code, out) = get(&format!("{f}=alpha%20one"));
    assert_eq!((code, out["count"].clone(), names(&out)), (200, json!(1), vec!["r1".to_string()]), "{out}");
    let (code, out) = get("q=BETA");
    assert_eq!((code, out["count"].clone(), names(&out)), (200, json!(1), vec!["r2".to_string()]), "{out}");
    // NEGATIVE PROOF: a value no row holds answers zero, so the filter really runs
    let (code, out) = get(&format!("{f}=gamma"));
    assert_eq!((code, out["count"].clone()), (200, json!(0)), "{out}");
    // a field the class does not have is refused by name, never answered empty
    let (code, out) = get("nosuchfield=x");
    assert_eq!((code, out["error"].as_str()), (400, Some("unknown-field")), "{out}");
    assert!(out["message"].as_str().unwrap().contains("nosuchfield"), "{out}");
}

/// #4744 (Kade, #4749 scroll-back; AC7 "the latest prompt") — a stream reads newest first
/// (`sort=-<field>`) and pages back in time (`<field>.lt=<value>`), in the store.
#[test]
fn a_stream_sorts_newest_first_and_pages_back_by_a_bound() {
    let (c, f) = CLASSES.iter()
        .find_map(|c| c.fields.iter().find(|f| !f.link && !f.many && f.datatype == "string" && f.allowed.is_empty()).map(|f| (c, f.name)))
        .expect("a class with a free string field");
    let store = Sparql::over(Box::new(Embedded::memory()));
    for (n, v) in [("a", "2026-10-26T09:00:00Z"), ("b", "2026-10-26T10:00:00Z"), ("c", "2026-10-26T08:00:00Z")] {
        let cells = [(f.to_string(), vec![crate::rules::Cell::Literal(v.into(), "string")])];
        store.write(c.graph, &iri(c, n), Some(c.name), &cells, false).unwrap();
    }
    let ctx = ctx(&store);
    let path = format!("/{}/{}/{}", crate::model::PRODUCT, c.domain, c.segment);
    let names = |q: &str| {
        let (code, out) = crate::route(&ctx, "GET", &format!("{path}?{q}"), None, "");
        assert_eq!(code, 200, "{out}");
        out["data"].as_array().unwrap().iter().map(|r| r["name"].as_str().unwrap().to_string()).collect::<Vec<_>>()
    };
    assert_eq!(names(&format!("sort=-{f}")), ["b", "a", "c"]);
    assert_eq!(names(&format!("sort={f}")), ["c", "a", "b"]);
    assert_eq!(names(&format!("sort=-{f}&{f}.lt=2026-10-26T10:00:00Z&limit=1")), ["a"]);
    // NEGATIVE PROOF: a bound below every row leaves nothing, so the bound really runs
    assert!(names(&format!("{f}.lt=2026-01-01")).is_empty());
    // a bound on a number would compare as text: refused by name (Kade's review)
    if let Some((nc, nf)) = CLASSES.iter().find_map(|c| c.fields.iter().find(|f| !f.link && matches!(f.datatype, "integer" | "decimal")).map(|f| (c, f.name))) {
        let (code, out) = crate::route(&ctx, "GET", &format!("/{}/{}/{}?{nf}.lt=5", crate::model::PRODUCT, nc.domain, nc.segment), None, "");
        assert_eq!((code, out["error"].as_str()), (400, Some("unordered-field")), "{out}");
    }
    // sorting by a field the class does not have is refused by name
    let (code, out) = crate::route(&ctx, "GET", &format!("{path}?sort=-nosuch"), None, "");
    assert_eq!((code, out["error"].as_str()), (400, Some("unknown-field")), "{out}");
}

